if not player then
Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
player=Players.LocalPlayer
end
local now=os.time()
local sessionKey=table.concat({
tostring(game.PlaceId),
tostring(game.JobId or ""),
tostring(now),
tostring(math.random(1,2^30)),
tostring(player.UserId or 0)
},"|")
local hash=0
local signed=sessionKey .. "MIYAKO_v1_SECRET_CHANGE_ME"
for i=1,#signed do
hash=(hash * 31 + signed:byte(i)) % 2^31
end
getgenv().MIYAKO_SESSION={
Key=sessionKey,
Signature=HttpService:GenerateGUID(false),
Fingerprint=tostring(hash),
PlaceId=game.PlaceId,
JobId=game.JobId,
UserId=player.UserId,
Time=now,
Version=1
}
end
local _SECRET_SALT="MIYAKO_v1_SECRET_CHANGE_ME"
local function _HMAC(str,salt)
local out=0
for i=1,#str do
out=(out * 31 + str:byte(i)) % 2^31
end
return tostring(out)
end
local _S=getgenv().MIYAKO_SESSION
if type(_S) ~="table"
or _S.Version ~=1
or _S.UserId ~=game:GetService("Players").LocalPlayer.UserId
or (os.time() - (_S.Time or 0)) > 600
or type(_S.Signature) ~="string"
or #_S.Signature < 30
then
warn("[MIYAKO] Unauthorized execution blocked.")
return
end
if _S.Fingerprint ~=_HMAC((_S.Key or "") .. _SECRET_SALT,_SECRET_SALT) then
warn("[MIYAKO] Fingerprint mismatch.")
return
end
