function MIYAKO:NormalizeIconId(iconId)
if not iconId or iconId=="" then
return "";
end;
iconId=tostring(iconId);
if string.match(iconId,"^%d+$") then
return "rbxassetid://" .. iconId;
end;
if string.find(iconId,"rbxassetid://",1,true)
or string.find(iconId,"rbxasset://",1,true)
or string.match(iconId,"^https?://") then
return iconId;
end;
return iconId;
end;
function MIYAKO:LoadIconLibrary()
if MIYAKO.IconLibraryLoaded then
return MIYAKO.Icons;
end;
if MIYAKO.IconLibraryLoading then
local timeout=0
repeat
task.wait(0.1)
timeout=timeout + 0.1
until not MIYAKO.IconLibraryLoading or timeout > 3
return MIYAKO.Icons;
end;
MIYAKO.IconLibraryLoading=true;
local function Load(path)
local success,result=pcall(function()
return loadstring(game:HttpGet(MIYAKO.IconBase .. path))();
end);
if success and typeof(result)=="table" then
return result;
end;
return {};
end;
pcall(function()
local defaultIcons=Load("src/elements/icon/basic.lua");
local lucideIcons=Load("src/elements/icon/lucide.lua");
local solarIcons=Load("src/elements/icon/solar.lua");
for name,id in pairs(defaultIcons) do
MIYAKO.Icons[name]=MIYAKO:NormalizeIconId(id);
end;
for name,id in pairs(lucideIcons) do
MIYAKO.Icons["lucide:" .. name]=MIYAKO:NormalizeIconId(id);
end;
for name,id in pairs(solarIcons) do
MIYAKO.Icons["solar:" .. name]=MIYAKO:NormalizeIconId(id);
end;
end)
MIYAKO.IconLibraryLoaded=true;
MIYAKO.IconLibraryLoading=false;
