local function _ApplyTheme(theme)
MIYAKO.AccentColor=theme.Accent or MIYAKO.AccentColor;
MIYAKO.MainColor=theme.Background or MIYAKO.MainColor;
MIYAKO.IconColor=theme.Icon or MIYAKO.IconColor;
for _,fn in next,MIYAKO.ThemeCallbacks do
pcall(fn,theme);
end;
if MIYAKO.SetTextGradientEnabled then
MIYAKO:SetTextGradientEnabled(MIYAKO.TextGradientEnabled);
end;
end;

function MIYAKO:AddTheme(Config)
Config=Config or {};
Config.Name=Config.Name or "Custom Theme";
local theme={
Name=Config.Name,
Accent=Config.Accent or MIYAKO.AccentColor,
Background=Config.Background or MIYAKO.MainColor,
Surface=Config.Surface or Color3.fromRGB(20,22,27),
Outline=Config.Outline or Color3.fromRGB(45,48,58),
Text=Config.Text or Color3.fromRGB(255,255,255),
Placeholder=Config.Placeholder or Color3.fromRGB(140,140,155),
Button=Config.Button or MIYAKO.AccentColor,
Icon=Config.Icon or MIYAKO.IconColor,
};
table.insert(MIYAKO.Themes,theme);
_ApplyTheme(theme);
return theme;
end;
