local function _applyIcon(src)
if not src or src=="" then
IconLabel.Text="";
IconImage.Image="";
IconLabel.Visible=false;
IconImage.Visible=true;
return;
end;
if tostring(src):find("rbxthumb://",1,true) or tostring(src):find("rbxassetid://",1,true) then
IconImage.Image=src
IconImage.Size=UDim2.fromScale(1,1)
IconImage.ScaleType=Enum.ScaleType.Crop
else
MIYAKO:SetIconMode(IconImage,src)
end
IconImage.Visible=true;
IconLabel.Visible=false;
end;
_applyIcon(iconImage);
local function _setIconVisible(val)
MenuIconLib.Visible=val;
local IconFallbackText=IconImage:FindFirstChild("ModernIconFallbackText");
if val then
MIYAKO.PlayAnimate(IconRoot,VSlowTween,{
BackgroundTransparency=0,
});
