else
MIYAKO.PlayAnimate(IconRoot,VSlowTween,{
BackgroundTransparency=1,
});
MIYAKO.PlayAnimate(UIStrokeIcon,SlowyTween,{
Transparency=1,
});
MIYAKO.PlayAnimate(IconLabel,SlowyTween,{
TextTransparency=1,
});
MIYAKO.PlayAnimate(IconImage,SlowyTween,{
ImageTransparency=1,
});
if IconFallbackText then
MIYAKO.PlayAnimate(IconFallbackText,SlowyTween,{
TextTransparency=1,
});
end;
IconShadow:Render(false);
end;
end;
