do
local dragging=false;
local dragStart,startPos;
local function clampPosition(pos)
local screenSize=MIYAKO.ScreenGui.AbsoluteSize;
local sz2=MenuIconLib._size;
local nx=math.clamp(pos.X.Offset,0,screenSize.X - sz2);
local ny=math.clamp(pos.Y.Scale * screenSize.Y + pos.Y.Offset,sz2/2,screenSize.Y - sz2/2);
return UDim2.new(0,nx,0,ny);
end;
local dragging=false;
local dragStart,startPos;
local DRAG_THRESHOLD=6;
MIYAKO:AddSignal(IconRoot.InputBegan:Connect(function(input)
if input.UserInputType ~=Enum.UserInputType.MouseButton1
and input.UserInputType ~=Enum.UserInputType.Touch then
return;
end;
dragging=false;
dragStart=input.Position;
startPos=IconRoot.Position;
local moved=false;
local moveConn,endConn;
moveConn=UserInputService.InputChanged:Connect(function(mv)
if mv.UserInputType ~=Enum.UserInputType.MouseMovement
and mv.UserInputType ~=Enum.UserInputType.Touch then return;end;
local delta=mv.Position - dragStart;
if delta.Magnitude > DRAG_THRESHOLD and MenuIconLib._draggable then
moved=true;
dragging=true;
local raw=UDim2.new(
startPos.X.Scale,startPos.X.Offset + delta.X,
startPos.Y.Scale,startPos.Y.Offset + delta.Y
);
IconRoot.Position=clampPosition(raw);
end;
end);
endConn=input.Changed:Connect(function()
if input.UserInputState ~=Enum.UserInputState.End then return;end;
moveConn:Disconnect();
endConn:Disconnect();
dragging=false;
if not moved then
if MIYAKO.ActiveWindow then
MIYAKO.ActiveWindow.Signal:SetValue(true)
MenuIconLib:SetVisible(false)
end
end;
end);
end));
end;
MIYAKO:OnThemeChanged(function(theme)
if theme.Icon then
MenuIconLib:SetIconColor(theme.Icon);
end;
if theme.Accent and not Config.StrokeColor then
MenuIconLib:SetStrokeColor(strokeColor);
end;
end);
_setIconVisible(true);
return MenuIconLib;
end;
if getcustomasset then
local link="https://github.com/4lpaca-pin/L2Hub/blob/main/assets/%s?raw=true";
local dir='L2Assets';
if not isfolder(dir) then
makefolder(dir);
end;
local function SafeFetch(name)
local path=dir..'/'..name;
if isfile(path) then
return getcustomasset(path);
end;
local ok,byte=pcall(function()
return game:HttpGet(string.format(link,name));
end);
if not ok or not byte or byte=="" then
return nil;
end;
local write_ok=pcall(writefile,path,byte);
if not write_ok then
return nil;
end;
task.wait();
if isfile(path) then
local ok2,asset=pcall(getcustomasset,path);
if ok2 then
return asset;
end;
end;
return nil;
end;
task.spawn(function()
local gradient=SafeFetch('saturation_value_gradient.png');
if gradient then
MIYAKO.ImageColorMapping=gradient;
end;
end);
end;
function MIYAKO:YieldUIBuild()
if not self.BuildingUI then return end
local now=os.clock()
if now - (self.UIBuildSlice or now) >=0.004 then
task.wait()
self.UIBuildSlice=os.clock()
end
end
function MIYAKO:AddSignal(RBXSignal)
if MIYAKO.UnloadEnabled then
table.insert(MIYAKO.GlobalSignals,RBXSignal);
end;
return RBXSignal;
end;
MIYAKO:AddSignal(GlobalWindow.DescendantAdded:Connect(function(Object)
task.defer(function()
MIYAKO:ApplyFont(Object);
end);
end));
function MIYAKO:AddQuery(ItemRoot: Frame,Name : string)
local SectionOwner=nil;
local Parent=ItemRoot;
while Parent do
if MIYAKO.SectionOwners[Parent] then
SectionOwner=MIYAKO.SectionOwners[Parent];
break;
end;
Parent=Parent.Parent;
end;
table.insert(MIYAKO.NameRegisitry,{
Root=ItemRoot,
Idx=Name,
Section=SectionOwner,
});
end;
function MIYAKO:RevealQueryItem(Query)
if not Query or not Query.Root then
return;
end;
if Query.Section and Query.Section.GetCollapsed and Query.Section:GetCollapsed() then
Query.Section:SetCollapsed(false);
end;
task.defer(function()
local Root=Query.Root;
if not Root or not Root.Parent then
return;
end;
local ScrollParent=Root.Parent;
while ScrollParent and not ScrollParent:IsA("ScrollingFrame") do
ScrollParent=ScrollParent.Parent;
end;
if not ScrollParent then
return;
end;
local CanvasMaxY=math.max(0,ScrollParent.AbsoluteCanvasSize.Y - ScrollParent.AbsoluteSize.Y);
local TargetY=Root.AbsolutePosition.Y - ScrollParent.AbsolutePosition.Y + ScrollParent.CanvasPosition.Y - 8;
ScrollParent.CanvasPosition=Vector2.new(
ScrollParent.CanvasPosition.X,
math.clamp(TargetY,0,CanvasMaxY)
);
end);
end;
function MIYAKO:RegisterFlag(Flag,Object)
if not Flag or not Object then
return Object;
end;
Flag=tostring(Flag);
MIYAKO.Flags[Flag]=Object;
if MIYAKO.PendingFlagValues[Flag] ~=nil and Object.SetValue then
local PendingValue=MIYAKO.PendingFlagValues[Flag];
MIYAKO.PendingFlagValues[Flag]=nil;
task.spawn(function()
pcall(function()
Object:SetValue(PendingValue);
end);
end);
end;
return Object;
end;
function MIYAKO:ResolveConfigFlag(Config)
if typeof(Config) ~="table" then
return nil;
end;
local Flag=Config.Flag or Config.Key or Config.ConfigKey;
if Flag ~=nil then
Flag=tostring(Flag);
Config.Flag=Flag;
end;
return Flag;
end;
function MIYAKO:AttachLockMethods(Object,Frame,Config)
if not Object or not Frame then
return Object;
end;
Config=Config or {};
local LockObject=MIYAKO:ApplyLock(Frame,Config.Locked==true,Config.TextLocked or Config.LockMessage or "Locked");
Object.Lock=LockObject;
function Object:SetLocked(state)
LockObject:SetLocked(state);
return Object;
end;
function Object:SetTextLocked(text)
LockObject:SetTextLocked(text);
return Object;
end;
function Object:GetLocked()
return LockObject:GetLocked();
end;
return Object;
end;
function Encryption.new(data: string)
local bytes={};
local encrypt_seed=((#data + 3782) % 111) + 1;
string.gsub(data,'.',CTN_NO_VIRTUALIZE(function(dt)
table.insert(bytes,tostring(dt:byte() + encrypt_seed));
end));
local concatbyte=table.concat(bytes,'?');
table.clear(bytes);
return "{"..tostring(encrypt_seed + 72667).."}?"..concatbyte;
end;
function Encryption.reverse(data: string)
local main_data=string.split(data,'?');
local seed_str=main_data[1]:gsub('{',''):gsub('}','');
local seed=tonumber(seed_str);
local ks={};
local real_seed=seed - 72667;
for i,v in next,main_data do
if i > 1 then
local fake_byte=tonumber(v);
table.insert(ks,string.char(fake_byte - real_seed))
end;
end;
local data=table.concat(ks);
table.clear(ks);
return data;
end;
do
local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
MIYAKO.Base64Encode=CTN_NO_VIRTUALIZE(function(data)
return ((data:gsub('.',function(x)
local r,b='',x:byte()
for i=8,1,-1 do r=r..(b%2^i-b%2^(i-1)>0 and '1' or '0') end
return r;
end)..'0000'):gsub('%d%d%d?%d?%d?%d?',function(x)
if (#x < 6) then return '' end
local c=0
for i=1,6 do c=c+(x:sub(i,i)=='1' and 2^(6-i) or 0) end
return b:sub(c+1,c+1)
end)..({'','==','='})[#data%3+1])
end);
MIYAKO.Base64Decode=CTN_NO_VIRTUALIZE(function(data)
data=string.gsub(data,'[^'..b..'=]','')
return (data:gsub('.',function(x)
if (x=='=') then return '' end
local r,f='',(b:find(x)-1)
for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
return r;
end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
if (#x ~=8) then return '' end
local c=0
for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
return string.char(c)
end))
end);
end;
