function MIYAKO:_ApplyTextGradient(Label)
if not Label or not Label.Parent then
return;
end;
local Gradient=Label:FindFirstChild("ModernTextGradient");
if not MIYAKO.TextGradientEnabled then
if Gradient then
Gradient:Destroy();
end;
return;
end;
if not Gradient then
Gradient=Instance.new("UIGradient");
Gradient.Name="ModernTextGradient";
Gradient.Parent=Label;
end;
local Accent=MIYAKO.AccentColor or Color3.fromRGB(0,255,100);
local SweepX=(((MIYAKO.TextGradientAnimationTime or 0) * 0.9) % 2) - 1;
Gradient.Rotation=0;
Gradient.Color=ColorSequence.new({
ColorSequenceKeypoint.new(0,Accent:Lerp(Color3.new(1,1,1),0.2)),
ColorSequenceKeypoint.new(0.55,Color3.new(1,1,1)),
ColorSequenceKeypoint.new(1,Accent:Lerp(Color3.new(1,1,1),0.35)),
});
Gradient.Offset=Vector2.new(SweepX,0);
for _,ExistingGradient in ipairs(MIYAKO.TextGradientObjects) do
if ExistingGradient==Gradient then
return Gradient;
end;
end;
table.insert(MIYAKO.TextGradientObjects,Gradient);
return Gradient;
end;
function MIYAKO:AddTextGradient(Label)
if not Label then
return Label;
end;
for _,ExistingLabel in ipairs(MIYAKO.TextGradientLabels) do
if ExistingLabel==Label then
MIYAKO:_ApplyTextGradient(Label);
return Label;
end;
end;
table.insert(MIYAKO.TextGradientLabels,Label);
MIYAKO:_ApplyTextGradient(Label);
return Label;
end;
function MIYAKO:SetTextGradientEnabled(Enabled)
MIYAKO.TextGradientEnabled=Enabled==true;
if not MIYAKO.TextGradientEnabled then
MIYAKO.TextGradientAccumulator=0;
end;
table.clear(MIYAKO.TextGradientObjects);
for Index=#MIYAKO.TextGradientLabels,1,-1 do
local Label=MIYAKO.TextGradientLabels[Index];
if Label and Label.Parent then
MIYAKO:_ApplyTextGradient(Label);
else
table.remove(MIYAKO.TextGradientLabels,Index);
end;
end;
end;
function MIYAKO:AnimateTextGradients(dt)
if not MIYAKO.TextGradientEnabled then
return;
end;
MIYAKO.TextGradientAccumulator=(MIYAKO.TextGradientAccumulator or 0) + (dt or 0);
if MIYAKO.TextGradientAccumulator < (1 / 30) then
return;
end;
local ResolvedDt=MIYAKO.TextGradientAccumulator;
MIYAKO.TextGradientAccumulator=0;
MIYAKO.TextGradientAnimationTime=(MIYAKO.TextGradientAnimationTime or 0) + ResolvedDt;
local SweepX=((MIYAKO.TextGradientAnimationTime * 0.9) % 2) - 1;
local Offset=Vector2.new(SweepX,0);
for Index=#MIYAKO.TextGradientObjects,1,-1 do
local Gradient=MIYAKO.TextGradientObjects[Index];
if Gradient and Gradient.Parent then
Gradient.Rotation=0;
Gradient.Offset=Offset;
else
table.remove(MIYAKO.TextGradientObjects,Index);
end;
end;
end;
MIYAKO:AddSignal(RunService.RenderStepped:Connect(function(dt)
MIYAKO:AnimateTextGradients(dt);
end));
