end
local active=MIYAKO.ActiveTweens[Self]
if active and active.Tween.PlaybackState==Enum.PlaybackState.Playing then
local same=true
for key,value in pairs(Property)do if active.Goals[key]~=value then same=false;break end end
if same then
for key in pairs(active.Goals)do if Property[key]==nil then same=false;break end end
end
if same then return active.Tween end
end
local changes={}
for key,value in pairs(Property)do if Self[key]~=value then changes[key]=value end end
if next(changes)==nil then return end
local Tween=TweenService:Create(Self,Info or TweenInfo.new(0.15),changes);
MIYAKO.ActiveTweens[Self]={Tween=Tween,Goals=Property}
Tween:Play();
