end;
RefreshLockSize();
local FeedbackBusy=false;
MIYAKO:AddSignal(LockOverlay.MouseButton1Click:Connect(function()
if FeedbackBusy or not LockOverlay.Parent then
return;
end;
FeedbackBusy=true;
MIYAKO.PlayAnimate(LockOverlay,TweenInfo.new(0.08),{
BackgroundTransparency=0.18,
});
task.delay(0.12,function()
if LockOverlay and LockOverlay.Parent then
MIYAKO.PlayAnimate(LockOverlay,TweenInfo.new(0.12),{
BackgroundTransparency=0.28,
});
end;
FeedbackBusy=false;
end);
end));
end;
BuildOverlay();
MIYAKO:AddSignal(Frame.DescendantRemoving:Connect(function(desc)
if desc==LockOverlay and LockFunc.IsLocked and not Destroyed then
if Rebuilding then
return;
end;
Rebuilding=true;
task.defer(function()
BuildOverlay();
Rebuilding=false;
end);
end;
end));
MIYAKO:AddSignal(Frame.AncestryChanged:Connect(function(_,newParent)
if newParent==nil then
Destroyed=true;
end;
end));
function LockFunc:SetLocked(state)
LockFunc.IsLocked=state==true;
if LockFunc.IsLocked and (not LockOverlay or not LockOverlay.Parent) then
BuildOverlay();
end;
if LockOverlay and LockOverlay.Parent then
LockOverlay.Visible=LockFunc.IsLocked;
end;
return LockFunc;
end;
function LockFunc:SetTextLocked(text)
Message=tostring(text or "Locked");
if LockLabel and LockLabel.Parent then
LockLabel.Text=Message;
RefreshLockSize();
end;
return LockFunc;
end;
function LockFunc:SetMessage(text)
return LockFunc:SetTextLocked(text);
end;
function LockFunc:GetLocked()
return LockFunc.IsLocked;
end;
LockFunc:SetLocked(LockFunc.IsLocked);
return LockFunc;
end;
MIYAKO.EnabledBlur=false;
MIYAKO.BlurModuleParent=workspace.CurrentCamera;
MIYAKO.GetCalculatePosition=CTN_NO_VIRTUALIZE(function(planePos,planeNormal,rayOrigin,rayDirection)
local n=planeNormal;
local d=rayDirection;
local v=rayOrigin - planePos;
local num=(n.x * v.x) + (n.y * v.y) + (n.z * v.z);
local den=(n.x * d.x) + (n.y * d.y) + (n.z * d.z);
local a=-num / den;
return rayOrigin + (a * rayDirection);
end);
MIYAKO.CreateBlurModule=CTN_NO_VIRTUALIZE(function(self,Frame,Signal)
if not MIYAKO.EnabledBlur then
return {Disconnect=function()end};
end;
local Part=Instance.new('Part',MIYAKO.BlurModuleParent);
local DepthOfField=Instance.new('DepthOfFieldEffect',cloneref(game:GetService('Lighting')));
local BlockMesh=Instance.new("BlockMesh");
BlockMesh.Parent=Part;
Part.Material=Enum.Material.Glass;
Part.Transparency=1;
Part.Reflectance=1;
Part.CastShadow=false;
Part.Anchored=true;
Part.CanCollide=false;
Part.CanQuery=false;
Part.CollisionGroup=MIYAKO.RandomString();
Part.Size=Vector3.new(1,1,1) * 0.01;
Part.Color=Color3.fromRGB(0,0,0);
DepthOfField.Enabled=true;
DepthOfField.FarIntensity=0;
DepthOfField.FocusDistance=0;
DepthOfField.InFocusRadius=1000;
DepthOfField.NearIntensity=1;
DepthOfField.Name=MIYAKO.RandomString();
Part.Name=MIYAKO.RandomString();
local disconnect;
local UpdateFunction=function()
local IsWindowActive=Signal:GetValue();
if IsWindowActive and not MIYAKO.Global3DRenderMode then
MIYAKO.PlayAnimate(DepthOfField,TweenInfo.new(0.1),{
NearIntensity=1
})
MIYAKO.PlayAnimate(Part,TweenInfo.new(0.1),{
Transparency=0.97,
Size=Vector3.new(1,1,1) * 0.01;
})
Part.Parent=MIYAKO.BlurModuleParent;
else
MIYAKO.PlayAnimate(DepthOfField,TweenInfo.new(0.1),{
NearIntensity=0
})
MIYAKO.PlayAnimate(Part,TweenInfo.new(0.1),{
Size=Vector3.zero,
Transparency=1.5,
})
Part.Parent=nil;
return false;
end;
if IsWindowActive then
local corner0=Frame.AbsolutePosition;
local corner1=corner0 + Frame.AbsoluteSize;
local ray0=CurrentCamera.ScreenPointToRay(CurrentCamera,corner0.X,corner0.Y,1);
local ray1=CurrentCamera.ScreenPointToRay(CurrentCamera,corner1.X,corner1.Y,1);
local planeOrigin=CurrentCamera.CFrame.Position + CurrentCamera.CFrame.LookVector * (0.05 - CurrentCamera.NearPlaneZ);
local planeNormal=CurrentCamera.CFrame.LookVector;
local pos0=MIYAKO.GetCalculatePosition(planeOrigin,planeNormal,ray0.Origin,ray0.Direction);
local pos1=MIYAKO.GetCalculatePosition(planeOrigin,planeNormal,ray1.Origin,ray1.Direction);
pos0=CurrentCamera.CFrame:PointToObjectSpace(pos0);
pos1=CurrentCamera.CFrame:PointToObjectSpace(pos1);
local size=pos1 - pos0;
local center=(pos0 + pos1) / 2;
BlockMesh.Offset=center
BlockMesh.Scale=size / 0.0101;
Part.CFrame=CurrentCamera.CFrame;
end;
end;
local rbxsignal=MIYAKO:AddSignal(CurrentCamera:GetPropertyChangedSignal('CFrame'):Connect(UpdateFunction))
local loopThread=MIYAKO:AddSignal(UserInputService.InputChanged:Connect(function(Input)
if Input.UserInputType==Enum.UserInputType.MouseButton1 or Input.UserInputType==Enum.UserInputType.MouseMovement or Input.UserInputType==Enum.UserInputType.Touch then
pcall(UpdateFunction);
end;
end));
local THREAD=task.spawn(function()
while true do task.wait(0.1)
pcall(UpdateFunction);
end;
end);
disconnect=function()
rbxsignal:Disconnect();
loopThread:Disconnect();
task.cancel(THREAD);
Part:Destroy();
DepthOfField:Destroy();
end;
Frame.Destroying:Connect(disconnect);
return rbxsignal;
end);
local EmptyFunction=function() end;
function MIYAKO:FireCallback(Callback,Context,...)
if type(Callback) ~="function" then
return true;
end;
local Args=table.pack(...);
local Window=MIYAKO.ActiveWindow;
local Ok,Result=xpcall(function()
return Callback(table.unpack(Args,1,Args.n));
end,(debug and debug.traceback) or tostring);
if not Ok then
warn(("[MIYAKO] %s callback error: %s"):format(tostring(Context or "Unknown"),tostring(Result)));
if Window and Window.NotifyOnCallbackError and Window.Notify then
Window:Notify({
Title="Callback Error",
Content=tostring(Result),
Duration=5,
Icon="lucide:triangle-alert",
});
end;
end;
return Ok,Result;
end;
local function CaseInsensitive(t)
return setmetatable(t,{
__index=function(self,key)
local v=rawget(self,key);
if v ~=nil then return v;end;
local lower=string.lower(tostring(key));
for k,val in next,self do
if string.lower(tostring(k))==lower then
return val;
end;
end;
end;
});
end;
