Three='3',
Four='4',
Five='5',
Six='6',
Seven='7',
Eight='8',
Nine='9',
Zero='0',
['Minus']="-",
['Plus']="+",
BackSlash="\\",
Slash="/",
Period='.',
Semicolon=';',
Colon=":",
LeftControl="LCtrl",
RightControl="RCtrl",
LeftShift="LShift",
RightShift="RShift",
Return="Enter",
LeftBracket="[",
RightBracket="]",
Quote="'",
Comma=",",
Equals="=",
LeftSuper="Super",
RightSuper="Super",
LeftAlt="LAlt",
RightAlt="RAlt",
Escape="Esc",
};
MIYAKO.EnumReverse={};
for i,v in next,MIYAKO.KeyEnum do
MIYAKO.EnumReverse[v]=i;
end;
function MIYAKO:NormalizeKeybindValue(K)
if K==nil then
return "None";
end;
if typeof(K)=="EnumItem" then
return K.Name;
end;
if typeof(K)=="table" and K.Name ~=nil then
return tostring(K.Name);
end;
return tostring(K);
end;
function MIYAKO:KeyCodeToStr(K: Enum.KeyCode)
local KeyName=MIYAKO:NormalizeKeybindValue(K);
if MIYAKO.KeyEnum[KeyName] then
return MIYAKO.KeyEnum[KeyName];
end;
return KeyName;
end;
function MIYAKO:StrToKeyCode(str: string)
str=MIYAKO:NormalizeKeybindValue(str);
if MIYAKO.EnumReverse[str] then
return Enum.KeyCode[MIYAKO.EnumReverse[str]];
end;
return Enum.KeyCode[str] or Enum.KeyCode.Unknown;
end;
