end;
if not IsSameKey(Input) then
return;
end;
if Config.Mode=="Hold" then
if not HoldState then
HoldState=true;
FireAction(true);
end;
else
ToggleState=not ToggleState;
FireAction(ToggleState);
end;
end))
MIYAKO:AddSignal(UserInputService.InputEnded:Connect(function(Input)
if Config.Mode ~="Hold" or not HoldState or not IsSameKey(Input) then
return;
end;
HoldState=false;
FireAction(false);
end))
