if ToneOrTint ~=nil then
if typeof(ToneOrTint)=="Color3" then
Config.Color=ToneOrTint;
else
Config.Tone=ToneOrTint;
end;
MIYAKO.PlayAnimate(ValueLabel,SlowyTween,{TextColor3=ToneColor()});
end;
end;
task.wait(Rate);
end;
end);
