local function UpdateProgress()
local MaxValue=math.max(tonumber(Config.Max) or 1,0.0001);
local Value=math.clamp(tonumber(Config.Value) or 0,0,MaxValue);
local Percent=Value / MaxValue;
local DisplayValue=MIYAKO.Rounding(Value,2);
local DisplayMax=MIYAKO.Rounding(MaxValue,2);
if Config.Type=="%" then
ValueLabel.Text=tostring(MIYAKO.Rounding(Percent * 100,0)).."%";
else
ValueLabel.Text=tostring(DisplayValue).."/"..tostring(DisplayMax)..tostring(Config.Type or "");
end;
MIYAKO.PlayAnimate(BarFill,SlowyTween,{
Size=UDim2.fromScale(Percent,1),
BackgroundColor3=MIYAKO.AccentColor
});
end;
function Progress:SetValue(value)
Config.Value=tonumber(value) or Config.Value;
UpdateProgress();
return Progress;
end;
function Progress:GetValue()
return Config.Value;
end;
function Progress:SetMax(max)
Config.Max=tonumber(max) or Config.Max;
UpdateProgress();
return Progress;
end;
function Progress:SetText(text)
Config.Name=tostring(text or "");
Title.Text=Config.Name;
return Progress;
end;
function Progress:SetType(text)
Config.Type=tostring(text or "");
UpdateProgress();
return Progress;
end;
function Progress:SetVisible(value)
ProgressFrame.Visible=value ~=false;
return Progress;
end;
Progress.SetRender=CTN_NO_VIRTUALIZE(function(value)
MIYAKO.PlayAnimate(Title,SlowyTween,{TextTransparency=value and 0.250 or 1});
MIYAKO.PlayAnimate(ValueLabel,SlowyTween,{TextTransparency=value and 0.500 or 1});
MIYAKO.PlayAnimate(BarBack,SlowyTween,{BackgroundTransparency=value and 0 or 1});
MIYAKO.PlayAnimate(BarFill,SlowyTween,{BackgroundTransparency=value and 0 or 1});
MIYAKO.PlayAnimate(LineFrame,SlowyTween,{BackgroundTransparency=value and 0.650 or 1});
end);
UpdateProgress();
Progress.SetRender(Signel:GetValue());
Signel:Connect(Progress.SetRender);
return CaseInsensitive(Progress);
end;
