end;
if SectionFrame.Size ~=UDim2.new(1,-5,0,TargetHeight) then SectionFrame.Size=UDim2.new(1,-5,0,TargetHeight) end
MIYAKO.PlayAnimate(SectionFrame,VSlowTween,{
})
end;
