ImageTransparency=(Config.Icon and tostring(Config.Icon) ~="") and 0.500 or 1
})
MIYAKO.PlayAnimate(SectionLabel,SlowyTween,{
TextTransparency=0.500
})
MIYAKO.PlayAnimate(SectionHandler,SlowyTween,{
BackgroundTransparency=0.500
})
MIYAKO.PlayAnimate(UIStroke,SlowyTween,{
Transparency=0.650
})
else
MIYAKO.PlayAnimate(SectionIcon,SlowyTween,{
ImageTransparency=1
})
MIYAKO.PlayAnimate(SectionLabel,SlowyTween,{
TextTransparency=1
})
MIYAKO.PlayAnimate(SectionHandler,SlowyTween,{
BackgroundTransparency=1
})
MIYAKO.PlayAnimate(UIStroke,SlowyTween,{
Transparency=1
})
end;
RenderCollapsedState();
end);
