MIYAKO:CreateInput(BottomFrame,CTN_NO_VIRTUALIZE(function()
if reciveSignal then
reciveSignal:Disconnect();
reciveSignal=nil;
end;
UserSettings.Signal:SetValue(true);
reciveSignal=UserInputService.InputBegan:Connect(function(Input)
if Input.UserInputType==Enum.UserInputType.MouseButton1 or Input.UserInputType==Enum.UserInputType.Touch then
if not MIYAKO:IsMouseOverFrame(UserSettings.Root) and not MIYAKO:IsMouseOverFrame(BottomFrame) and not MIYAKO.IsMosueOverOtherFrame then
if reciveSignal then
reciveSignal:Disconnect();
reciveSignal=nil;
end;
UserSettings.Signal:SetValue(false);
end
end
end);
end))
Window.UserSettings=UserSettings;
