end))
MIYAKO:AddSignal(Input.MouseLeave:Connect(function()
MIYAKO.PlayAnimate(Button,SlowyTween,{BackgroundTransparency=Primary and 0.100 or 0.250})
end))
MIYAKO.PlayAnimate(Button,SlowyTween,{BackgroundTransparency=Primary and 0.100 or 0.250})
