Icon.ImageColor3=Color3.fromRGB(186,186,186)
Icon.ImageTransparency=1
Icon.ScaleType=Enum.ScaleType.Fit
Content.Name=MIYAKO.RandomString();
Content.Parent=IndicatorItem
Content.AnchorPoint=Vector2.new(0,0.5)
Content.BackgroundColor3=Color3.fromRGB(186,186,186)
Content.BackgroundTransparency=1.000
Content.BorderColor3=Color3.fromRGB(0,0,0)
Content.BorderSizePixel=0
Content.Position=UDim2.new(0,40,0.5,0)
Content.Size=UDim2.new(1,-40,0,25)
Content.ZIndex=17
Content.Font=Enum.Font.GothamBold
Content.Text=Config.Name
Content.TextColor3=Color3.fromRGB(186,186,186)
Content.TextSize=20.000
Content.TextTransparency=1
Content.TextXAlignment=Enum.TextXAlignment.Left
Indicator.Update=CTN_NO_VIRTUALIZE(function()
local text=TextService:GetTextSize(Content.Text,Content.TextSize,Content.Font,Vector2.new(math.huge,math.huge));
MIYAKO.PlayAnimate(IndicatorItem,SlowyTween,{
Size=UDim2.new(0,text.X + 60,0,40);
})
end);
Indicator.SetRender=CTN_NO_VIRTUALIZE(function(self,value)
Indicator.Visible=value;
if value then
MIYAKO.PlayAnimate(IndicatorItem,SlowyTween,{
BackgroundTransparency=0.200
});
MIYAKO.PlayAnimate(Line,SlowyTween,{
BackgroundTransparency=0,
BackgroundColor3=Indicators.Color[Indicator.CurrentColor]
});
MIYAKO.PlayAnimate(Icon,VSlowTween,{
TextTransparency=0.250,
TextColor3=Indicators.Color[Indicator.CurrentColor]
});
MIYAKO.PlayAnimate(Content,VSlowTween,{
TextTransparency=0.2,
TextColor3=Indicators.Color[Indicator.CurrentColor]
});
Shadow:Render(false);
else
MIYAKO.PlayAnimate(IndicatorItem,SlowyTween,{
BackgroundTransparency=1
});
MIYAKO.PlayAnimate(Line,SlowyTween,{
BackgroundTransparency=1,
BackgroundColor3=Indicators.Color[Indicator.CurrentColor]
});
MIYAKO.PlayAnimate(Icon,VSlowTween,{
TextTransparency=1,
TextColor3=Indicators.Color[Indicator.CurrentColor]
});
MIYAKO.PlayAnimate(Content,VSlowTween,{
TextTransparency=1,
TextColor3=Indicators.Color[Indicator.CurrentColor]
});
Shadow:Render(false);
end;
Indicator.Update();
end);
Indicator.Update();
Indicator:SetRender(false);
function Indicator:SetColor(new_color)
Indicator.CurrentColor=new_color;
if Indicator.Visible then
Indicator:SetRender(true);
end;
end;
function Indicator:SetText(name)
Config.Name=name;
Content.Text=Config.Name;
Indicator.Update();
end;
return CaseInsensitive(Indicator);
end;
return CaseInsensitive(Indicators);
end;
MIYAKO.Logging=MIYAKO:CreateLogger();
MIYAKO.Notifier=MIYAKO:CreateNotification();
MIYAKO.Indicators=MIYAKO:CreateIndicator();
function MIYAKO:Unload()
if not MIYAKO.UnloadEnabled then
return;
end;
if MIYAKO.Unloaded then return end
MIYAKO.Unloaded=true
if MIYAKO.ActiveWindow then MIYAKO.ActiveWindow.Destroyed=true end
for _,entry in pairs(MIYAKO.ActiveTweens or {})do pcall(function()entry.Tween:Cancel()end)end
table.clear(MIYAKO.ActiveTweens)
MIYAKO.ScreenGui:Destroy();
for i,v in next,MIYAKO.GlobalSignals do
pcall(v.Disconnect,v)
end;
table.clear(MIYAKO.GlobalSignals)
end;
function MIYAKO:Window(Config)
return MIYAKO:CreateWindow(Config);
end;
return CaseInsensitive(MIYAKO);
end)()
local MiyakoEnv=(getgenv and getgenv()) or _G
if type(MiyakoEnv.MIYAKO_UpgradeCleanup)=="function" then pcall(MiyakoEnv.MIYAKO_UpgradeCleanup) end
if type(_G.VD_Cleanup)=="function" then pcall(_G.VD_Cleanup);_G.VD_Cleanup=nil end
local MiyakoRuntime={Alive=true,Cleanup={}}
local function MiyakoUpgradeCleanup()
if not MiyakoRuntime.Alive then return end
MiyakoRuntime.Alive=false
for _,cleanup in ipairs(MiyakoRuntime.Cleanup) do pcall(cleanup) end
MIYAKO:Unload()
end
MiyakoEnv.MIYAKO_UpgradeCleanup=MiyakoUpgradeCleanup
