local lastScan,lastFire,lastHook=0,0,0
local generators,gates,hooks={},{},{}
local savedSkillMode
local function notify(status)
farm.Status=status
if farm.StatusLabel then farm.StatusLabel:SetText("Status: "..status) end
end
local function remote(folder,name)
local remotes=repStorage:FindFirstChild("Remotes")
local group=remotes and remotes:FindFirstChild(folder)
local value=group and group:FindFirstChild(name)
return value and value:IsA("RemoteEvent") and value or nil
end
local function fire(value,...)
if not value then return false end
return pcall(value.FireServer,value,...)
end
local function attribute(object,name)
if not object then return nil end
local value=object:GetAttribute(name)
if value~=nil then return value end
local child=object:FindFirstChild(name)
return child and child:IsA("ValueBase") and child.Value or nil
end
local function blocked(object)
return attribute(object,"Knocked")==true or attribute(object,"IsHooked")==true
or attribute(object,"IsCarried")==true or attribute(object,"IsDead")==true
end
local function role(player)
local label=tostring(player:GetAttribute("Role") or (player.Team and player.Team.Name) or ""):lower()
if player:GetAttribute("IsKiller")==true or label:find("killer") then return "Killer" end
if label:find("surviv") then return "Survivor" end
return "Lobby"
end
local function part(object,keyword)
if not object then return nil end
if object:IsA("BasePart") and (not keyword or object.Name:lower():find(keyword)) then return object end
for _,child in ipairs(object:GetDescendants()) do
if child:IsA("BasePart") and (not keyword or child.Name:lower():find(keyword)) then return child end
end
return not keyword and object:IsA("Model") and object.PrimaryPart or nil
end
local function scan()
if tick()-lastScan<3 then return end
lastScan=tick();generators={};gates={};hooks={}
local map=workspace:FindFirstChild("Map")
if not map then return end
local seen={}
for _,object in ipairs(map:GetDescendants()) do
local name=object.Name:lower()
if object:IsA("Model") and (name:find("generator") or object:GetAttribute("RepairProgress")~=nil) then
if part(object,"generatorpoint") and not seen[object] then generators[#generators+1]=object;seen[object]=true end
elseif object:IsA("BasePart") and name:find("generatorpoint") then
local model=object.Parent
if not seen[model] then generators[#generators+1]=model;seen[model]=true end
end
if object:IsA("BasePart") and object.Name=="HookPoint" then hooks[#hooks+1]=object end
if object:IsA("BasePart") and (name=="exitlever" or name=="lever") then gates[#gates+1]=object end
end
end
local function stopInteraction()
if currentRemote and currentPoint then
if currentKind=="Repair" then fire(currentRemote,currentPoint,false,nil,session,Players.LocalPlayer.Character)
else fire(currentRemote,currentPoint,false) end
end
currentPoint=nil;currentRemote=nil;currentKind=nil
StopRepairAnim()
end
local function move(target)
local position=target.Position
if (root.Position-position).Magnitude<=4 then return true end
if farm.Walk then
humanoid:MoveTo(position)
return false
end
root.CFrame=target
root.AssemblyLinearVelocity=Vector3.zero
return true
end
local function nearestKiller(position)
local nearest,distance=nil,math.huge
for _,player in ipairs(Players:GetPlayers()) do
if player~=Players.LocalPlayer and role(player)=="Killer" then
local target=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
if target then local d=(target.Position-position).Magnitude;if d<distance then nearest,distance=target,d end end
end
end
return nearest,distance
end
local function completed(gen)
if attribute(gen,"Completed")==true then return true end
local progress=tonumber(attribute(gen,"RepairProgress") or attribute(gen,"ProgressRepair"))
return progress~=nil and progress>=100
end
local function startInteraction(point,kind)
local value=kind=="Repair" and remote("Generators","RepairEvent") or remote("Exit","LeverEvent")
if not value then stopInteraction();notify("Interaction remote unavailable");return end
if currentPoint~=point or currentKind~=kind then stopInteraction();lastFire=0 end
currentPoint,currentRemote,currentKind=point,value,kind
if not move(point.CFrame+Vector3.new(0,1.5,0)) then notify("Moving to target");return end
if tick()-lastFire>=0.8 then
lastFire=tick()
if kind=="Repair" then fire(value,point,true,nil,session,character);PlayRepairAnim()
else fire(value,point,true) end
end
notify(kind=="Repair" and "Repairing generator" or "Opening gate")
end
local function survivor()
local _,danger=nearestKiller(root.Position)
if farm.AvoidKiller and danger<farm.SafeDistance then
stopInteraction();notify("Paused: killer nearby");return
end
if farm.Rescue then
for _,player in ipairs(Players:GetPlayers()) do
local target=player.Character
if player~=Players.LocalPlayer and target and attribute(target,"IsHooked")==true then
local point,best=nil,math.huge
local targetRoot=target:FindFirstChild("HumanoidRootPart")
if targetRoot then
for _,hook in ipairs(hooks) do local distance=(hook.Position-targetRoot.Position).Magnitude;if distance<best then point,best=hook,distance end end
end
if point and best<12 then
local _,risk=nearestKiller(point.Position)
if not farm.AvoidKiller or risk>=farm.SafeDistance then
stopInteraction()
if move(point.CFrame+Vector3.new(0,2,0)) then fire(remote("Carry","UnHookEvent"),point) end
notify("Rescuing survivor");return
end
end
end
end
end
local chosen,point,shortest=nil,nil,math.huge
for _,gen in ipairs(generators) do
if gen.Parent and not completed(gen) and attribute(gen,"ProgressPaused")~=true then
local target=part(gen,"generatorpoint")
if target then
local _,risk=nearestKiller(target.Position)
local distance=(root.Position-target.Position).Magnitude
if distance<shortest and (not farm.AvoidKiller or risk>=farm.SafeDistance) then chosen,point,shortest=gen,target,distance end
end
end
end
if chosen then startInteraction(point,"Repair");return end
local gate,best=nil,math.huge
