end
if gate then
local owner=gate.Parent
local open=attribute(gate,"Open")==true or attribute(owner,"Open")==true or attribute(owner,"Opened")==true
local progress=tonumber(attribute(gate,"Progress") or attribute(owner,"GateProgress"))
open=open or (progress~=nil and progress>=100)
if open then
local map=workspace:FindFirstChild("Map")
local finish
if map then for _,object in ipairs(map:GetDescendants())do
local name=object.Name:lower()
if object:IsA("BasePart") and (name:find("finishline") or name:find("fininshline"))then finish=object;break end
end end
if finish then stopInteraction();move(finish.CFrame+Vector3.new(0,2,0));notify("Moving to exit");return end
end
startInteraction(gate,"Gate")
else stopInteraction();notify("Waiting for generator or gate") end
end
local function killer()
stopInteraction()
local carrying=attribute(character,"IsCarrying")==true or attribute(Players.LocalPlayer,"IsCarrying")==true
if carrying then
local target,best=nil,math.huge
for _,hook in ipairs(hooks) do
if hook.Parent and not attribute(hook,"Occupied") and not attribute(hook.Parent,"Occupied") then
local distance=(root.Position-hook.Position).Magnitude
if distance<best then target,best=hook,distance end
end
end
if target then
if move(CFrame.new(target.Position+Vector3.new(0,1.5,1.8),target.Position)) and tick()-lastHook>=2 then
lastHook=tick();fire(remote("Carry","HookEvent"),target)
local chosen=target
