local targetRoot=target:FindFirstChild("HumanoidRootPart")
if attribute(target,"Knocked")==true then
if move(targetRoot.CFrame) and tick()-lastFire>=0.8 then lastFire=tick();fire(remote("Carry","CarrySurvivorEvent"),target) end
notify("Carrying survivor")
else
local position=targetRoot.Position-targetRoot.CFrame.LookVector*1.2
if move(CFrame.new(position,targetRoot.Position)) and tick()-lastFire>=0.6 then
lastFire=tick();fire(remote("Attacks","Lunge"));fire(remote("Attacks","BasicAttack"))
end
notify("Chasing survivor")
end
end
function farm:SetMode(mode)
stopInteraction()
if savedSkillMode then VDSettings.Survivor.AutoSkillMode=savedSkillMode;savedSkillMode=nil end
self.Mode=mode
if mode=="Survivor" then
savedSkillMode=VDSettings.Survivor.AutoSkillMode
VDSettings.Survivor.AutoSkillMode="Perfect"
Cache.AutoRepairEnabled=false;StopAutoRepair()
end
notify(mode=="Off" and "Off" or "Waiting for a round and the selected role")
end
function farm:Step()
if self.Mode=="Off" then return end
character=Players.LocalPlayer.Character
root=character and character:FindFirstChild("HumanoidRootPart")
humanoid=character and character:FindFirstChildOfClass("Humanoid")
if not root or not humanoid or humanoid.Health<=0 or blocked(character) then stopInteraction();notify("Waiting for character");return end
if role(Players.LocalPlayer)~=self.Mode then stopInteraction();notify("Waiting for the selected role");return end
scan()
if self.Mode=="Survivor" then survivor() else killer() end
end
table.insert(MiyakoRuntime.Cleanup,function() farm:SetMode("Off") end)
task.spawn(function()
while MiyakoRuntime.Alive do
if farm.Mode~="Off" then local ok,err=pcall(function()farm:Step()end);if not ok then stopInteraction();notify("Waiting for game objects");warn("[MIYAKO Farm]",err)end end
task.wait(farm.Mode=="Off" and 0.75 or 0.25)
end
stopInteraction()
end)
return farm
end)()

