local MiyakoMoonwalk={
Active=false,Character=nil,SavedSpeed=nil,SavedAutoRotate=nil,
Button=nil,Container=nil,Locked=false,Dragging=false,
DragStart=nil,StartPos=nil,DragDistance=0,
SavedPos=UDim2.new(0.03,0,0.4,0),
}
local MoonwalkMainToggle,MoonwalkFloatingToggle
local function RestoreMiyakoMoonwalk()
local c=MiyakoMoonwalk.Character
local h=c and c:FindFirstChildOfClass("Humanoid")
if h then
if MiyakoMoonwalk.SavedAutoRotate ~=nil then h.AutoRotate=MiyakoMoonwalk.SavedAutoRotate end
if MiyakoMoonwalk.SavedSpeed ~=nil then h.WalkSpeed=MiyakoMoonwalk.SavedSpeed end
end
MiyakoMoonwalk.Character=nil
MiyakoMoonwalk.SavedSpeed=nil
MiyakoMoonwalk.SavedAutoRotate=nil
end
local function RefreshMiyakoMoonwalkButton()
local button=MiyakoMoonwalk.Button
if not button or not button.Parent then return end
button.BackgroundColor3=VDSettings.Misc.Moonwalk and Color3.fromRGB(55,8,10) or Color3.fromRGB(22,22,27)
local status=button:FindFirstChild("Status")
if status then
status.Text=VDSettings.Misc.Moonwalk and "ON" or "OFF"
status.TextColor3=VDSettings.Misc.Moonwalk and Color3.fromRGB(255,50,60) or Color3.fromRGB(140,140,150)
end
end
local function SetMiyakoMoonwalk(enabled,updateControl)
enabled=enabled and MiyakoRuntime.Alive or false
VDSettings.Misc.Moonwalk=enabled
if enabled and MiyakoRuntime.Expansion then MiyakoRuntime.Expansion.DisableMoonwalk()end
if enabled then
if not MiyakoMoonwalk.Connection then
MiyakoMoonwalk.Connection=RunService.PreSimulation:Connect(function()
if MiyakoMoonwalk.Update then MiyakoMoonwalk.Update() end
end)
end
else
if MiyakoMoonwalk.Connection then MiyakoMoonwalk.Connection:Disconnect();MiyakoMoonwalk.Connection=nil end
RestoreMiyakoMoonwalk()
end
RefreshMiyakoMoonwalkButton()
if updateControl and MoonwalkMainToggle then
if MoonwalkMainToggle:GetValue() ~=enabled then MoonwalkMainToggle:SetValue(enabled) end
end
end
local function CreateMiyakoMoonwalkButton()
if MiyakoMoonwalk.Container and MiyakoMoonwalk.Container.Parent then
MiyakoMoonwalk.Container.Visible=VDSettings.Misc.MoonwalkButton and MiyakoRuntime.Alive
return
end
MiyakoMoonwalk.Button,MiyakoMoonwalk.Container=nil,nil
if not VDSettings.Misc.MoonwalkButton or not MiyakoRuntime.Alive then return end
local container=Instance.new("Frame")
container.Name="MIYAKO_MoonwalkFloating"
container.Size=UDim2.fromOffset(218,40)
container.Position=MiyakoMoonwalk.SavedPos
container.BackgroundTransparency=1
container.ZIndex=80
container.Parent=MIYAKO.ScreenGui
MiyakoMoonwalk.Container=container
local function mkButton(name,text,x,width)
local b=Instance.new("TextButton")
b.Name=name
b.Text=text
b.Font=Enum.Font.GothamBold
b.TextSize=12
b.TextColor3=Color3.fromRGB(255,225,225)
b.BackgroundColor3=Color3.fromRGB(22,22,27)
b.BorderSizePixel=0
b.AutoButtonColor=false
b.Position=UDim2.fromOffset(x,0)
b.Size=UDim2.fromOffset(width,40)
b.ZIndex=81
b.Parent=container
local corner=Instance.new("UICorner")
corner.CornerRadius=UDim.new(0,10)
corner.Parent=b
local stroke=Instance.new("UIStroke")
stroke.Color=Color3.fromRGB(110,35,46)
stroke.Thickness=1.2
stroke.Parent=b
return b
end
local main=mkButton("MIYAKO_Moonwalk","MIYAKO Moonwalk",0,132)
MiyakoMoonwalk.Button=main
main.TextXAlignment=Enum.TextXAlignment.Left
main.Text="  Moonwalk"
local status=Instance.new("TextLabel")
status.Name="Status"
status.Text="OFF"
status.Font=Enum.Font.GothamBold
status.TextSize=10
status.Size=UDim2.fromOffset(34,24)
status.Position=UDim2.new(1,-38,0.5,-12)
status.BackgroundTransparency=1
status.ZIndex=82
status.Parent=main
local lock=mkButton("MIYAKO_Lock","UNLOCK",136,39)
lock.TextSize=9
lock.Text="FREE"
local close=mkButton("MIYAKO_Close","X",179,39)
close.TextColor3=Color3.fromRGB(255,75,75)
main.MouseButton1Click:Connect(function()
if MiyakoMoonwalk.DragDistance < 8 then SetMiyakoMoonwalk(not VDSettings.Misc.Moonwalk,true) end
end)
main.InputBegan:Connect(function(input)
if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
MiyakoMoonwalk.DragDistance=0
MiyakoMoonwalk.DragStart=input.Position
MiyakoMoonwalk.StartPos=container.Position
MiyakoMoonwalk.Dragging=not MiyakoMoonwalk.Locked
end
end)
main.InputEnded:Connect(function(input)
if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
MiyakoMoonwalk.Dragging=false
end
end)
lock.MouseButton1Click:Connect(function()
MiyakoMoonwalk.Locked=not MiyakoMoonwalk.Locked
MiyakoMoonwalk.Dragging=false
lock.Text=MiyakoMoonwalk.Locked and "LOCK" or "FREE"
end)
close.MouseButton1Click:Connect(function()
VDSettings.Misc.MoonwalkButton=false
if MoonwalkFloatingToggle and MoonwalkFloatingToggle:GetValue() ~=false then
MoonwalkFloatingToggle:SetValue(false)
end
if MiyakoMoonwalk.Container then MiyakoMoonwalk.Container.Visible=false end
end)
RefreshMiyakoMoonwalkButton()
end
MIYAKO:AddSignal(UserInputService.InputChanged:Connect(function(input)
if not MiyakoRuntime.Alive or not MiyakoMoonwalk.Dragging then return end
if input.UserInputType ~=Enum.UserInputType.Touch and input.UserInputType ~=Enum.UserInputType.MouseMovement then return end
local start,pos=MiyakoMoonwalk.DragStart,MiyakoMoonwalk.StartPos
if not start or not pos or not MiyakoMoonwalk.Container then return end
local delta=input.Position - start
MiyakoMoonwalk.DragDistance=math.abs(delta.X) + math.abs(delta.Y)
MiyakoMoonwalk.Container.Position=UDim2.new(pos.X.Scale,pos.X.Offset+delta.X,pos.Y.Scale,pos.Y.Offset+delta.Y)
MiyakoMoonwalk.SavedPos=MiyakoMoonwalk.Container.Position
end))
MIYAKO:AddSignal(UserInputService.InputBegan:Connect(function(input,processed)
if processed or input.KeyCode ~=Enum.KeyCode.F9 or not MiyakoRuntime.Alive then return end
SetMiyakoMoonwalk(not VDSettings.Misc.Moonwalk,true)
end))
local function UpdateMiyakoMoonwalk()
if not VDSettings.Misc.Moonwalk or not MiyakoRuntime.Alive then return end
local char=Players.LocalPlayer.Character
local root=char and char:FindFirstChild("HumanoidRootPart")
local humanoid=char and char:FindFirstChildOfClass("Humanoid")
local camera=workspace.CurrentCamera
if not root or not humanoid or humanoid.Health <=0 or not camera then return end
if MiyakoMoonwalk.Character ~=char then
RestoreMiyakoMoonwalk()
MiyakoMoonwalk.Character=char
MiyakoMoonwalk.SavedSpeed=humanoid.WalkSpeed
MiyakoMoonwalk.SavedAutoRotate=humanoid.AutoRotate
end
humanoid.AutoRotate=false
humanoid.WalkSpeed=VDSettings.Misc.MoonwalkSpeed
local look=camera.CFrame.LookVector
local cameraFlat=Vector3.new(look.X,0,look.Z)
if cameraFlat.Magnitude < 0.001 then return end
cameraFlat=cameraFlat.Unit
local direction=root.CFrame.LookVector
local facing=Vector3.new(direction.X,0,direction.Z)
if facing.Magnitude < 0.001 then return end
local waveAngle=math.rad(VDSettings.Misc.MoonwalkWaveAngle * math.sin(os.clock() * VDSettings.Misc.MoonwalkWaveSpeed))
if facing.Unit:Dot(cameraFlat) > 0 then
root.CFrame=CFrame.lookAt(root.Position,root.Position+cameraFlat) * CFrame.Angles(0,waveAngle,0)
humanoid:Move(-cameraFlat,false)
else
root.CFrame=CFrame.lookAt(root.Position,root.Position-cameraFlat) * CFrame.Angles(0,waveAngle,0)
humanoid:Move(cameraFlat,false)
end
end
MiyakoMoonwalk.Update=UpdateMiyakoMoonwalk
table.insert(MiyakoRuntime.Cleanup,function()
SetMiyakoMoonwalk(false,false)
if MiyakoMoonwalk.Container then MiyakoMoonwalk.Container:Destroy() end
end)
