ShowColon=true,
Rows={},
Update=function()
local Rows={}
if VDSettings.Misc.NextKiller then
local PlayersList=Players:GetPlayers()
table.sort(PlayersList,function(a,b)
local aAllow=a:GetAttribute("AllowKiller") or false
local bAllow=b:GetAttribute("AllowKiller") or false
if aAllow ~=bAllow then return aAllow end
return (a:GetAttribute("KillerChance") or 0) > (b:GetAttribute("KillerChance") or 0)
end)
local NextKiller=PlayersList[1]
local KillerText
if NextKiller then
KillerText=(NextKiller==Players.LocalPlayer) and "KAMU (You)" or NextKiller.Name
else
KillerText="Waiting..."
end
table.insert(Rows,{
Text="Next Killer",
Value=KillerText,
Tone="Error",
})
else
table.insert(Rows,{
Text="Next Killer",
Value="[Disabled]",
Tone="Muted",
})
end
if VDSettings.Misc.NextMap then
local MapFolder=workspace:FindFirstChild("Map")
local MapText
local MapTone
if MapFolder then
MapText=DetectMapName()
MapTone="Accent"
else
MapText="Lobby / Loading..."
MapTone="Warning"
end
table.insert(Rows,{
Text="Next Map",
Value=MapText,
Tone=MapTone,
})
else
table.insert(Rows,{
Text="Next Map",
Value="[Disabled]",
Tone="Muted",
})
end
return Rows
end,
})
task.spawn(function()
pcall(function()
if type(hookmetamethod)=="function" and type(getnamecallmethod)=="function" and type(checkcaller)=="function" then
local oldNamecall
oldNamecall=hookmetamethod(game,"__namecall",function(self,...)
local method=getnamecallmethod()
local args={...}
if MiyakoRuntime.Alive and not checkcaller() and method=="FireServer" and typeof(self)=="Instance" then
local sName=self.Name
if VDSettings.Survivor.AntiFall and sName=="Fall" then return end
if VDSettings.Survivor.Invis.State and sName=="UpdateCharacterLook" then
local newArgs={}
for i,v in ipairs(args) do
if typeof(v)=="CFrame" then newArgs[i]=v * CFrame.new(0,5000,0) else newArgs[i]=v end
end
return oldNamecall(self,unpack(newArgs))
end
if VDSettings.Killer.Spear.Enabled and sName=="Spearthrow" then
local aimVec=Cache.Spear.lookVector
if typeof(aimVec)=="Vector3" then
if typeof(args[1])=="table" and args[1].Direction ~=nil then
args[1].Direction=aimVec.Unit
elseif typeof(args[1])=="Vector3" then
args[1]=aimVec
end
end
return oldNamecall(self,unpack(args))
end
if VDSettings.Killer.ChainSilentAim and sName=="ChainThrow" then
local closest,minDst=nil,math.huge
local myChar=Players.LocalPlayer.Character
local myHRP=myChar and myChar:FindFirstChild("HumanoidRootPart")
local myPos=myHRP and myHRP.Position
if myPos then
for _,v in pairs(Players:GetPlayers()) do
if v ~=Players.LocalPlayer and v.Character and GetPlayerRole(v) ~="Killer" then
local hrp=v.Character:FindFirstChild("HumanoidRootPart")
local hum=v.Character:FindFirstChildOfClass("Humanoid")
local isDown=v.Character:GetAttribute("Knocked")==true or v.Character:GetAttribute("IsHooked")==true or v.Character:GetAttribute("Downed")==true
if hrp and hum and hum.Health > 0 and not isDown then
local dst=(hrp.Position - myPos).Magnitude
if dst < minDst then
minDst=dst
closest=v
end
end
end
end
end
if closest and args[1] and typeof(args[1])=="Vector3" then
local targetHRP=closest.Character:FindFirstChild("HumanoidRootPart")
local origin=(args[3] and typeof(args[3])=="table" and args[3].Origin) or myPos
if targetHRP and typeof(origin)=="Vector3" and (targetHRP.Position-origin).Magnitude>0.001 then
args[1]=(targetHRP.Position - origin).Unit
end
end
if type(setnamecallmethod)=="function" then setnamecallmethod(method)end
return oldNamecall(self,unpack(args))
end
if VDSettings.Aim.SilentAim and typeof(MiyakoGunState.Direction)=="Vector3" and self.Parent and self.Parent.Name=="Twist of Fate" then
if sName=="Fire" then
local index
if typeof(args[3])=="Vector3" then index=3
elseif typeof(args[2])=="Vector3" then index=2 end
if index then
args[index]=MiyakoGunState.Direction
MiyakoGunFireLaser()
return oldNamecall(self,unpack(args))
end
elseif sName=="VisualizeBullet" and typeof(MiyakoGunState.TargetPos)=="Vector3" then
for i=1,#args do
if typeof(args[i])=="Vector3" then
args[i]=args[i].Magnitude > 10 and MiyakoGunState.TargetPos or MiyakoGunState.Direction
elseif typeof(args[i])=="CFrame" then
local m=MiyakoGunState.Muzzle
if m then args[i]=CFrame.lookAt(m,MiyakoGunState.TargetPos) end
end
end
return oldNamecall(self,unpack(args))
end
end
end
return oldNamecall(self,...)
end)
end
end)
end)
Players.LocalPlayer.CharacterAdded:Connect(function(char)
task.wait(0.5)
SetupHeadIcon(char)
SetupFakePerks(char)
if VDSettings.Survivor.Invis.State then task.wait(0.5) ApplyInvisibility() end
end)
if Players.LocalPlayer.Character then
