local expansionOK,expansionError=pcall(function()
do
local HostWindow,HostLibrary,HostRuntime=Window,MIYAKO,MiyakoRuntime
local MainSettings=VDSettings
local inheritedEnv=(getgenv and getgenv()) or _G
local vendorEnv=setmetatable({VD={}},{__index=inheritedEnv})
local VD=vendorEnv.VD
local _G=vendorEnv
local getgenv=function() return vendorEnv end
local alive,ready=true,false
local controls,active,frames,objects,threads,connections={},{},{},{},{},{}
setmetatable(objects,{__mode="k"});setmetatable(threads,{__mode="k"})
local realTask,realInstance,realRunService=task,Instance,game:GetService("RunService")
local activeCount,lease=0,0
local function wake() lease=os.clock()+4 end
local function isActive() return activeCount>0 or os.clock()<lease end
local task=setmetatable({},{__index=realTask})
for _,method in ipairs({"spawn","defer","delay"}) do
task[method]=function(...)
if not alive then return end
local t=realTask[method](...);threads[t]=true;return t
end
end
function task.wait(delay)
if not alive then error("MIYAKO expansion stopped",0) end
return realTask.wait(not isActive() and math.max(tonumber(delay) or 0,0.2) or delay)
end
local Instance=setmetatable({new=function(...)
local obj=realInstance.new(...);objects[obj]=true;return obj
end},{__index=realInstance})
local function TrackConnect(signal,callback)
local c=signal:Connect(function(...)if alive then return callback(...)end end)
connections[c]=true;return c
end
local function frameSignal(kind)
local bucket={};frames[kind]=bucket
return {Wait=function()return realRunService[kind]:Wait()end,Connect=function(_,fn)
local c={Connected=true};bucket[c]=fn
function c:Disconnect() self.Connected=false;bucket[self]=nil end
return c
end}
end
local serviceProxy=setmetatable({RenderStepped=frameSignal("RenderStepped"),Heartbeat=frameSignal("Heartbeat"),Stepped=frameSignal("Stepped")},{__index=function(_,k)
local v=realRunService[k]
if type(v)=="function" then return function(_,...)return v(realRunService,...)end end
return v
end})
for _,kind in ipairs({"RenderStepped","Heartbeat","Stepped"})do
local c=realRunService[kind]:Connect(function(...)
if not alive or not ready or not isActive() then return end
for conn,fn in pairs(frames[kind])do
if conn.Connected and os.clock()>=(conn.RetryAfter or 0) then
local ok,err=pcall(fn,...)
if not ok then
conn.RetryAfter=os.clock()+2
warn("[MIYAKO Expansion] "..kind..": "..tostring(err))
end
end
end
end)
connections[c]=true
end
