local function makeSection(category,title)
local skipped=suppressedSections[title] or category=="Config"
local native
local function box()
if not native then
local target
if title=="Auto Parry"then target=SubTabCombat
elseif title=="Silent Aim TOF"or title=="Aim Lock Gun"then
pages.Pistol=pages.Pistol or AimTabbox:AddTab({Name="Pistol V2",Icon="crosshairs"});target=pages.Pistol
else target=page(category)end
native=target:AddDependencyGroupbox({Name=renameSections[title] or title,Icon="layers",Collapsible=true,Collapsed=true})
end
return native
end
local section={__title=title,__pageName=category}
local function add(kind,opts)
opts=opts or {};local name=tostring(opts.Title or kind)
local value=opts.Default
local raw,handle
local constructing=true
local id="MIYAKO_Extra_"..category.."_"..title.."_"..tostring(opts.ConfigId or name)
id=id:gsub("[^%w_]","_")
local master=kind=="Toggle" and opts.Default~=true
local function callback(v)
value=v
if constructing then return end
if master then
local on=v==true
if active[id]~=on then activeCount=math.max(0,activeCount+(on and 1 or -1));active[id]=on end
end
if title=="Moonwalk"and name=="Enable Moonwalk"and v then SetMiyakoMoonwalk(false,true)end
if title=="Auto Parry"and name=="Enable Auto Parry"and v then stopOriginalParry()end
if title=="Silent Aim TOF"and name=="Enable Silent Aim TOF"and v then stopOriginalPistol()end
wake()
if type(opts.Callback)=="function"then opts.Callback(v)end
end
local hidden=skipped or (duplicateControls[title] and duplicateControls[title][name])
if not hidden then
local config={Name=name,Flag=id,Default=value,Callback=callback}
if kind=="Toggle"then
if master then config.Default=false end
raw=box():AddToggle(config)
elseif kind=="Slider"then
config.Min=opts.Min or 0;config.Max=opts.Max or 100
config.Default=tonumber(value)or config.Min
local step=tonumber(opts.Increment)or 1
config.Rounding=step<0.01 and 3 or step<0.1 and 2 or step<1 and 1 or 0
raw=box():AddSlider(config)
elseif kind=="Dropdown"then
config.Values=opts.Options or {};config.Multi=opts.Multi==true
raw=box():AddDropdown(config)
elseif kind=="Input"then
config.Placeholder=opts.Placeholder or "";raw=box():AddTextInput(config)
elseif kind=="ColorPicker"then raw=box():AddColorPicker(config)
elseif kind=="Keybind"then
config.Default=typeof(value)=="EnumItem"and value or Enum.KeyCode[tostring(value or "Unknown")]or Enum.KeyCode.Unknown
raw=box():AddKeybind(config)
elseif kind=="Button"then
raw=box():AddButton({Name=name,Callback=function()wake();if opts.Callback then opts.Callback()end end})
elseif kind=="Paragraph"then raw=box():AddLabel({Text=name.."\n"..tostring(opts.Content or opts.Description or "")})end
end
constructing=false
handle={Control=raw,Title=name,Section=title,Page=category}
function handle.Get() if raw and raw.GetValue then return raw:GetValue()end;return value end
function handle.Set(v,silent)
if raw and raw.SetValue and not silent then raw:SetValue(v)
elseif silent then value=v else callback(v)end
end
if not hidden and kind=="Toggle"then table.insert(controls,{Handle=handle,Callback=callback})end
if title=="Auto Parry"and name=="Enable Auto Parry"then extraParry=raw end
if title=="Moonwalk"and name=="Enable Moonwalk"then extraMoonwalk=raw end
if title=="Silent Aim TOF"and name=="Enable Silent Aim TOF"then extraPistol=raw end
return handle
end
for _,kind in ipairs({"Toggle","Slider","Dropdown","Input","ColorPicker","Keybind","Button","Paragraph"})do
section["Add"..kind]=function(_,opts)return add(kind,opts)end
end
return section
end
function __N3K0P01_UI_ADAPTER:Window()
return {InfoTab=function()end,AddTab=function(_,opts)
local category=opts.Name
return {AddSection=function(_,title)return makeSection(category,title)end}
end}
end
function __N3K0P01_UI_ADAPTER:MakeNotify(opts)
if alive and ready then HostWindow:Notify({Title="MIYAKO",Content=opts.Content or opts.Description or "",Duration=opts.Delay or 3})end
end
local function cleanupExpansion()
if not alive then return end
for _,entry in ipairs(controls)do
if entry.Handle.Get()==true then pcall(entry.Callback,false)end
end
alive=false;ready=false
for c in pairs(connections)do pcall(function()c:Disconnect()end)end
for t in pairs(threads)do if t~=coroutine.running()then pcall(realTask.cancel,t)end end
for obj in pairs(objects)do pcall(function()obj:Destroy()end)end
for key in pairs(VD)do if type(VD[key])=="boolean"then VD[key]=false end end
end
table.insert(HostRuntime.Cleanup,cleanupExpansion)
