W.__N3K0P01_AutoParryCleanup=AP_Cleanup
local function AP_Debug(message)
if not AP_Config.Debug then return end
local now=os.clock()
if now - AP_LastDebugPrint >=0.2 then
AP_LastDebugPrint=now
print("[MIYAKO Auto Parry V3] " .. tostring(message))
end
end
local function AP_GetRoot(character)
if not character then return nil end
local root=character:FindFirstChild("HumanoidRootPart")
if root and root:IsA("BasePart") then return root end
return nil
end
local function AP_IsKiller(player)
return player ~=nil and TeamIs(player,"Killer")
end
local function AP_IsDowned(character)
if not character then return true end
local state=character:GetAttribute("State")
return character:GetAttribute("Knocked")==true
or character:GetAttribute("IsHooked")==true
or character:GetAttribute("IsCarried")==true
or state=="Downed"
or state=="Dead"
end
local function AP_IsSafeToParry(character)
if not AP_Config.Safety then return true end
if not character then return false end
local interactable=character:FindFirstChild("CheckInterractable")
if not interactable then return true end
for _,attribute in ipairs({
"isVaulting","isRepairing","isUnhooking","isHealing","isSliding"
}) do
if interactable:GetAttribute(attribute)==true then return false end
end
return true
end
local function AP_IsUsable()
if not AP_Alive or not AP_Config.Enabled or GetRole() ~="Survivor" then return false end
if AP_State.ParryCooldown then return false end
local character=LocalPlayer.Character
if not character or AP_IsDowned(character) then return false end
local humanoid=character:FindFirstChildOfClass("Humanoid")
if humanoid and humanoid.Health <=0 then return false end
return AP_GetRoot(character) ~=nil
end
local function AP_GetCloseRange()
return math.clamp(tonumber(AP_Config.CloseRange) or 3,0.5,4)
end
local function AP_GetHitRange()
return math.clamp(tonumber(AP_Config.HitRange) or 9,3,20)
end
local function AP_GetKillerAimDirection(character)
if not character then return nil end
local part=character:FindFirstChild("Head")
or character:FindFirstChild("UpperTorso")
or character:FindFirstChild("Torso")
or character:FindFirstChild("HumanoidRootPart")
if not part or not part:IsA("BasePart") then return nil end
local look=part.CFrame.LookVector
local flat=Vector3.new(look.X,0,look.Z)
if flat.Magnitude <=0.05 then return nil end
return flat.Unit
end
local function AP_IsKillerFacingMe(killerRoot,myRoot,angleDegrees,killerCharacter)
if not killerRoot or not myRoot then return false end
local toMe=myRoot.Position - killerRoot.Position
local flatToMe=Vector3.new(toMe.X,0,toMe.Z)
if flatToMe.Magnitude < 0.05 then return true end
flatToMe=flatToMe.Unit
local aimDirection=AP_GetKillerAimDirection(killerCharacter)
if not aimDirection then
local look=killerRoot.CFrame.LookVector
local flatLook=Vector3.new(look.X,0,look.Z)
if flatLook.Magnitude < 0.05 then return true end
aimDirection=flatLook.Unit
end
return aimDirection:Dot(flatToMe) >=math.cos(math.rad(tonumber(angleDegrees) or 60))
end
local function AP_FaceCheck(killerRoot,myRoot,killerCharacter)
if not AP_Config.FaceEnabled then return true end
return AP_IsKillerFacingMe(
killerRoot,
myRoot,
AP_Config.FaceAngleDeg,
killerCharacter
)
end
local function AP_IsKillerCharging(killerCharacter,myRoot)
local killerRoot=AP_GetRoot(killerCharacter)
if not killerRoot or not myRoot then return false end
local velocity=killerRoot.AssemblyLinearVelocity
local flatVelocity=Vector3.new(velocity.X,0,velocity.Z)
if flatVelocity.Magnitude < 6 then return false end
local offset=myRoot.Position - killerRoot.Position
local flatOffset=Vector3.new(offset.X,0,offset.Z)
if flatOffset.Magnitude < 0.05 then return true end
return flatVelocity.Unit:Dot(flatOffset.Unit) >=0.5
end
local function AP_IsKillerInHitRange(killerCharacter,myRoot,distance)
local killerRoot=AP_GetRoot(killerCharacter)
if not killerRoot or not myRoot then return false end
distance=distance or (killerRoot.Position - myRoot.Position).Magnitude
local limit=AP_GetHitRange()
if AP_IsKillerCharging(killerCharacter,myRoot) then
limit=math.max(limit,18)
end
if AP_Config.Radius <=14 then
limit=math.max(limit,AP_Config.Radius)
end
return distance <=limit
end
local function AP_MarkKillerAttack(character,animationId)
if not character then return end
AP_KillerAttackState[character]={
t=os.clock(),
animId=tostring(animationId or ""),
}
AP_Debug("attack detected: " .. tostring(character.Name) .. " / " .. tostring(animationId))
end
local function AP_IsKillerAttacking(character)
local state=character and AP_KillerAttackState[character]
if not state then return false end
if os.clock() - state.t > 1.25 then
AP_KillerAttackState[character]=nil
return false
end
return true
end
