local function AP_HasDaggerVisual()
local function containsDagger(container)
if not container then return false end
for _,item in ipairs(container:GetDescendants()) do
local name=string.lower(item.Name)
if name:find("dagger",1,true)
or name:find("parry",1,true)
or name:find("deflect",1,true)
or name:find("parrying",1,true) then
return true
end
end
return false
end
return containsDagger(LocalPlayer.Character)
or containsDagger(LocalPlayer:FindFirstChild("Backpack"))
end
local function AP_TryUnlockAfterUnhook(reason)
if not AP_State.ParryCooldown then return false end
local character=LocalPlayer.Character
if not character then return false end
if character:GetAttribute("IsHooked")==true
or character:GetAttribute("IsCarried")==true
or character:GetAttribute("Knocked")==true then
return false
end
if AP_HasDaggerVisual() then
AP_State.ParryCooldown=false
AP_State.ParryCooldownUntil=nil
AP_UnhookRetries=0
AP_Debug("unhook: dagger found (" .. tostring(reason) .. ")")
return true
end
AP_UnhookRetries=AP_UnhookRetries + 1
if AP_UnhookRetries >=5 then
AP_State.ParryCooldown=false
AP_State.ParryCooldownUntil=nil
AP_UnhookRetries=0
AP_Debug("unhook: dagger not found after retries; cooldown reset")
return true
end
return false
end
local function AP_SetupUnhookListener(character)
if not character or AP_UnhookCharacter==character then return end
AP_UnhookCharacter=character
local function checkHookState()
local hooked=character:GetAttribute("IsHooked")==true
or character:GetAttribute("IsCarried")==true
or character:GetAttribute("Knocked")==true
if not hooked and AP_State.ParryCooldown and not AP_UnhookLocked then
AP_UnhookLocked=true
task.spawn(function()
task.wait(0.5)
AP_TryUnlockAfterUnhook("attribute")
task.wait(0.5)
AP_UnhookLocked=false
end)
end
end
AP_Reg(character:GetAttributeChangedSignal("IsHooked"):Connect(checkHookState))
AP_Reg(character:GetAttributeChangedSignal("IsCarried"):Connect(checkHookState))
AP_Reg(character:GetAttributeChangedSignal("Knocked"):Connect(checkHookState))
AP_Reg(TrackConnect(character.ChildAdded,function()
if AP_State.ParryCooldown and AP_HasDaggerVisual() then
task.defer(function() AP_TryUnlockAfterUnhook("character child") end)
end
end))
local backpack=LocalPlayer:FindFirstChild("Backpack")
if backpack then
AP_Reg(TrackConnect(backpack.ChildAdded,function()
if AP_State.ParryCooldown and AP_HasDaggerVisual() then
task.defer(function() AP_TryUnlockAfterUnhook("backpack child") end)
end
end))
end
end
local function AP_TapParryButton()
local playerGui=LocalPlayer:FindFirstChild("PlayerGui")
if not playerGui then return end
local survivorMob=playerGui:FindFirstChild("Survivor-mob")
local controls=survivorMob and survivorMob:FindFirstChild("Controls")
local button=controls and controls:FindFirstChild("Gui-mob")
if button and button.Visible and type(firesignal)=="function" then
pcall(function() firesignal(button.MouseButton1Down) end)
