local function APX_FindKillerFromInstance(instance)
local current=instance
while current and current ~=Workspace do
if current:IsA("Model") then
local player=Players:GetPlayerFromCharacter(current)
if player and AP_IsKiller(player) then return player,current end
end
current=current.Parent
end
return nil,nil
end
local function APX_FindNearestKiller(maxDistance)
local myRoot=AP_GetRoot(LocalPlayer.Character)
if not myRoot then return nil,nil,math.huge end
local bestPlayer,bestCharacter=nil,nil
local bestDistance=maxDistance or math.huge
for _,player in ipairs(Players:GetPlayers()) do
if player ~=LocalPlayer and AP_IsKiller(player) and player.Character then
local root=AP_GetRoot(player.Character)
if root then
local distance=(root.Position - myRoot.Position).Magnitude
if distance < bestDistance then
bestPlayer,bestCharacter,bestDistance=player,player.Character,distance
end
end
end
end
return bestPlayer,bestCharacter,bestDistance
end
local function APX_TryParry(killerCharacter,reason)
if not AP_IsUsable() then return false end
local now=os.clock()
if now - AP_LastHitboxTrigger < APX_TriggerCooldown then return false end
local myRoot=AP_GetRoot(LocalPlayer.Character)
local killerRoot=AP_GetRoot(killerCharacter)
if not myRoot or not killerRoot then return false end
AP_LastHitboxTrigger=now
AP_Debug("hitbox/lunge: " .. tostring(reason))
APX_ShowVisual(killerCharacter)
AP_ExecuteParry(true)
return true
end
AP_Reg(TrackConnect(Workspace.DescendantAdded,function(instance)
task.defer(function()
pcall(function()
if not instance or not instance:IsA("BasePart") then return end
if not APX_HitboxNames[string.lower(instance.Name)] then return end
if not AP_IsUsable() then return end
local myRoot=AP_GetRoot(LocalPlayer.Character)
if not myRoot then return end
local _,killerCharacter=APX_FindKillerFromInstance(instance)
if not killerCharacter then
local _,nearestCharacter,distance=APX_FindNearestKiller(20)
if distance <=20 then killerCharacter=nearestCharacter end
end
local killerRoot=AP_GetRoot(killerCharacter)
if killerRoot and (killerRoot.Position - myRoot.Position).Magnitude < 20 then
APX_TryParry(killerCharacter,"hitbox: " .. instance.Name)
end
end)
end)
end))
AP_Reg(TrackConnect(RunService.Heartbeat,function()
if not AP_IsUsable() then return end
local myRoot=AP_GetRoot(LocalPlayer.Character)
if not myRoot then return end
for _,player in ipairs(Players:GetPlayers()) do
if player ~=LocalPlayer and AP_IsKiller(player) and player.Character then
local killerCharacter=player.Character
local killerRoot=AP_GetRoot(killerCharacter)
if killerRoot then
local offset=myRoot.Position - killerRoot.Position
local distance=offset.Magnitude
if distance >=4 and distance <=16 and distance > 0.05 then
local velocity=killerRoot.AssemblyLinearVelocity
local flatVelocity=Vector3.new(velocity.X,0,velocity.Z)
local flatToMe=Vector3.new(offset.X,0,offset.Z)
if flatVelocity.Magnitude > 18 and flatToMe.Magnitude > 0.05 then
local towardDot=flatVelocity.Unit:Dot(flatToMe.Unit)
local attack=AP_KillerAttackState[killerCharacter]
local attackAge=attack and (os.clock() - (attack.t or 0)) or math.huge
if towardDot > 0.75 and attackAge >=0 and attackAge <=1.25 then
APX_TryParry(killerCharacter,"lunge")
break
end
end
end
end
end
end
end))
for _,player in ipairs(Players:GetPlayers()) do AP_SetupPlayer(player) end
