elseif isHooked then
AP_State.ParryCooldown=false
AP_State.ParryCooldownUntil=nil
else
local serverCooldown=tonumber(cooldownValue) or 60
if serverCooldown ~=serverCooldown or serverCooldown <=0 or serverCooldown > 600 then
serverCooldown=60
end
AP_State.ParryCooldown=true
AP_State.ParryCooldownUntil=os.clock() + serverCooldown
task.delay(serverCooldown,function()
if AP_Alive and AP_State.ParryCooldownUntil
and os.clock() >=AP_State.ParryCooldownUntil then
AP_State.ParryCooldown=false
AP_State.ParryCooldownUntil=nil
AP_Debug("server cooldown finished")
end
end)
end
end))
end)
if LocalPlayer.Character then AP_SetupUnhookListener(LocalPlayer.Character) end
