FaceEnabled="SURV_AutoParryFace",
AntiFake="SURV_AutoParryAntiFake",
FaceAngleDeg="SURV_AutoParryFaceAngle",
Aggressive="SURV_AutoParryAggressive",
Safety="SURV_AutoParrySafety",
ShowCircle="SURV_AutoParryCircle",
Radius="SURV_AutoParryRadius",
CloseRange="SURV_AutoParryCloseRange",
HitRange="SURV_AutoParryHitRange",
Debug="SURV_AutoParryDebug",
}
if keyMap[option] then
if option=="Radius" then
AP_Config[option]=math.clamp(tonumber(value) or 6,5,25)
elseif option=="CloseRange" then
AP_Config[option]=math.clamp(tonumber(value) or 3,0.5,4)
elseif option=="HitRange" then
AP_Config[option]=math.clamp(tonumber(value) or 9,3,20)
elseif option=="FaceAngleDeg" then
AP_Config[option]=math.clamp(tonumber(value) or 60,30,90)
else
AP_Config[option]=value==true
end
VD[keyMap[option]]=AP_Config[option]
end
end
end
