local actionLbl=pill:FindFirstChild("ActionLbl")
local hpBarBg=pill:FindFirstChild("HPBarBg")
local hpBarFill=hpBarBg and hpBarBg:FindFirstChild("HPBarFill")
local downPill=pill:FindFirstChild("DownPill")
