local dragging,dragStart,startPos=false,nil,nil
local moved=false
TrackConnect(btn.InputBegan,function(inp)
if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
if VD.SURV_FakeParryLocked then return end
dragging=true
moved=false
dragStart=inp.Position
startPos=btn.Position
end
end)
TrackConnect(btn.InputEnded,function(inp)
if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
if dragging and moved then
elseif not moved then
FakeParry_Play()
end
dragging=false
end
end)
TrackConnect(UserInputService.InputChanged,function(inp)
if not dragging or VD.SURV_FakeParryLocked then return end
if inp.UserInputType==Enum.UserInputType.MouseMovement or inp.UserInputType==Enum.UserInputType.Touch then
local d=inp.Position - dragStart
if math.abs(d.X) + math.abs(d.Y) > 6 then moved=true end
btn.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset + d.X,startPos.Y.Scale,startPos.Y.Offset + d.Y)
end
end)
FakeParryButtonGui=sg
FakeParryButton=btn
end
