statusLabel.TextColor3=Color3.fromRGB(120,255,120)
else
nameLabel.Text="Waiting..."
statusLabel.Text="Status: Lobby"
statusLabel.TextColor3=Color3.fromRGB(150,150,160)
end
end
lastExisted=mapExists
task.wait(0.5)
end
end)
end
