local music=makeSection("Misc","Music Player")
local musicSound=Instance.new("Sound");musicSound.Name="MIYAKO_Music";musicSound.Volume=0.5;musicSound.Parent=game:GetService("SoundService")
local songNames={};for i,song in ipairs(MUSIC_SONGS)do songNames[i]=song.name.." ["..i.."]"end
local currentSong,shuffle,repeatSong=1,false,false
local mini
local function musicPlay(index)
currentSong=((index-1)%#MUSIC_SONGS)+1
musicSound.SoundId=MUSIC_SONGS[currentSong].id
musicSound:Play()
if not active.Music then active.Music=true;activeCount+=1 end
if mini then mini.Text="MIYAKO | "..MUSIC_SONGS[currentSong].name end
end
local function musicStop()
musicSound:Stop()
if active.Music then active.Music=false;activeCount=math.max(0,activeCount-1)end
end
music:AddDropdown({Title="Track",Options=songNames,Default=songNames[1],Callback=function(v)
for i,n in ipairs(songNames)do if n==v then currentSong=i;if musicSound.IsPlaying then musicPlay(i)end;break end end
end})
music:AddButton({Title="Play / Pause",Callback=function()
if musicSound.IsPlaying then musicSound:Pause();if active.Music then active.Music=false;activeCount=math.max(0,activeCount-1)end
elseif musicSound.TimePosition>0 then musicSound:Resume();active.Music=true;activeCount+=1
else musicPlay(currentSong)end
end})
music:AddButton({Title="Previous Track",Callback=function()musicPlay(currentSong-1)end})
music:AddButton({Title="Next Track",Callback=function()musicPlay(shuffle and math.random(#MUSIC_SONGS)or currentSong+1)end})
music:AddButton({Title="Stop Playback",Callback=musicStop})
music:AddToggle({Title="Shuffle",Default=false,Callback=function(v)shuffle=v end})
music:AddToggle({Title="Repeat Current Track",Default=false,Callback=function(v)repeatSong=v end})
music:AddSlider({Title="Music Volume",Min=0,Max=100,Default=50,Increment=1,Callback=function(v)musicSound.Volume=v/100 end})
music:AddToggle({Title="Floating Mini Player",Default=false,Callback=function(v)
if not mini and v then
mini=Instance.new("TextButton");mini.Size=UDim2.fromOffset(240,34);mini.Position=UDim2.new(0.5,-120,0.08,0)
mini.BackgroundColor3=Color3.fromRGB(25,20,35);mini.TextColor3=Color3.fromRGB(220,200,255)
mini.Font=Enum.Font.GothamMedium;mini.TextSize=11;mini.Text="MIYAKO | Tap for next track";mini.Parent=HostLibrary.ScreenGui
local corner=Instance.new("UICorner");corner.CornerRadius=UDim.new(0,9);corner.Parent=mini
TrackConnect(mini.Activated,function()musicPlay(currentSong+1)end)
HostLibrary.Drag(mini,mini,0)
end
if mini then mini.Visible=v end
end})
TrackConnect(musicSound.Ended,function()musicPlay(repeatSong and currentSong or shuffle and math.random(#MUSIC_SONGS)or currentSong+1)end)
table.insert(HostRuntime.Cleanup,musicStop)
ready=true
lease=0
HostRuntime.Expansion.Ready=true
if HostWindow._ControlCountLabel then
local count=0;for _ in pairs(HostLibrary.Flags)do count+=1 end
HostWindow._ControlCountLabel.Text=tostring(count)
end
HostRuntime.Expansion.Controls=controls
HostRuntime.Expansion.Environment=vendorEnv
table.insert(HostRuntime.Cleanup,function()pcall(function()workspace:SetAttribute("MIYAKO_EXP_TOF_HOOKED",false)end)end)
end
end)
