for _,conn in ipairs(Cache.mapConnections or {})do pcall(function()conn:Disconnect()end)end
for _,player in ipairs(Players:GetPlayers())do pcall(ClearESP,player)end
for _,visual in pairs(Cache.WorldESPInstances or {})do
if visual.Highlight then visual.Highlight:Destroy()end
if visual.Billboard then visual.Billboard:Destroy()end
end
for _,drawing in pairs(Cache.Spear.Visuals or {})do pcall(function()drawing:Remove()end)end
end)
